"use strict";

function escapeRegExp(value) {
  return value.replace(/[|\\{}()[\]^$+?.]/g, "\\$&");
}

function globToRegExp(pattern) {
  let source = "^";
  for (let index = 0; index < pattern.length; index += 1) {
    const character = pattern[index];
    if (character === "*") {
      source += "[^/]*";
    } else if (character === "?") {
      source += "[^/]";
    } else {
      source += escapeRegExp(character);
    }
  }
  source += "$";
  return new RegExp(source);
}

function minimatch(value, pattern) {
  const normalizedValue = String(value).replace(/\\/g, "/");
  const normalizedPattern = String(pattern).replace(/\\/g, "/");
  return globToRegExp(normalizedPattern).test(normalizedValue);
}

minimatch.filter = function filter(pattern) {
  return function matcher(value) {
    return minimatch(value, pattern);
  };
};

module.exports = minimatch;
